        condition_tree={
            "condition_type": "planet_house",
            "planet": "Ketu",
            "house": 7,
            "chart": "d1"
        },
        interpretation_en="Ketu in the 7th house brings a philosophical or spiritually minded spouse, but can cause periodic feelings of emotional distance or unconventional relationship dynamics that require conscious emotional nurturing.",
        interpretation_ta="7-ஆம் பாவத்தில் ஞானகாரகன் கேது அமர்வது ஆன்மீக நாட்டம் கொண்ட வாழ்க்கைத் துணையையோ, அல்லது உலகியல் ஆசைகளில் பற்றற்ற மனநிலையையோ தந்து இல்லறத்தில் தனித்துவமான போக்கை உண்டாக்கும்.",
        astrological_principle_en="Ketu dissolves superficial romantic expectations and demands authentic spiritual bonding over transactional attachment.",
        astrological_principle_ta="கேது நின்ற பாவத்தின் வெளிப்படையான பற்றுகளைக் குறைத்து ஆழமான ஆன்ம ஞானத்தை நோக்கி வழிநடத்துவார்.",
        source_reference="Jataka Parijata, Ch. 14, Sloka 31",
        limitations_en="Benefic aspect from Venus or Jupiter creates deep mutual respect and philosophical synergy.",
        limitations_ta="சுக்கிரன் அல்லது குருவின் சேர்க்கை/பார்வை இருப்பின் பரஸ்பர ஆன்மீக தோழமை பலப்படும்.",
