        version=1,
        name_en="Jupiter Aspecting 7th House (Guru Drishti Protecting Marriage Sanctity)",
        name_ta="7-ஆம் பாவத்தை பார்க்கும் குரு பகவான் (மங்கலத் திருமண யோகம்)",
