        version=1,
        name_en="Mars in 10th House (Kuladipaka Yoga - Technical, Defense & Executive Power)",
        name_ta="10-ஆம் பாவத்தில் செவ்வாய் (குலதீபக யோகம் - பொறியியல் & தலைமை அதிகாரம்)",
