        rule_id="RULE-CAR-06",
        version=1,
        name_en="Jupiter in 10th House (Distinguished Advisor, Jurist & Academic Acumen)",
        name_ta="10-ஆம் பாவத்தில் குரு பகவான் (ஆலோசகர், நீதித்துறை & கல்வி மேன்மை)",
