        interpretation_en="The 6th lord occupying an Upachaya house (3rd, 6th, or 11th) empowers the native to overcome corporate rivals, conquer difficult competitive entrance tests, and build an unassailable career in executive service or legal arbitration.",
        interpretation_ta="6-ஆம் அதிபதி உபசய ஸ்தானங்களில் (3, 6, 11) அமர்வது எதிரிகளை வெல்லும் ஆற்றலையும், கடினமான போட்டித் தேர்வுகளில் வெற்றியடைந்து அரசு அல்லது பெருநிறுவன உயர் பதவிகளை அடையும் யோகத்தையும் நல்கும்.",
        astrological_principle_en="Upachaya placements improve continuously through exertion, transforming obstacles (Roga/Rina/Shatru) into career stepping stones.",
        astrological_principle_ta="உபசய ஸ்தான விதி: உழைப்பினால் தடைகளை தகர்த்து வெற்றியை அறுவடை செய்யும் அமைப்பாகும்.",
        source_reference="Uttara Kalamrita, Ch. 4, Sloka 22",
        limitations_en="Avoid unnecessary workplace litigation; channel fighting spirit toward exams and promotions.",
        limitations_ta="தேவையற்ற வழக்குகளைத் தவிர்த்து ஆற்றலை உத்தியோக உயர்வில் செலுத்த வேண்டும்.",
        severity=SeverityLevel.FAVORABLE,
