        astrological_principle_en="Fixed Fire sign ruled by Surya: The royal seat of the zodiac conferring sovereign dignity, moral courage, and protective warmth.",
        astrological_principle_ta="ஸ்திர அக்னி ராசி: சூரியனின் ஒளி இவர்களுக்கு இயற்கையான நிர்வாகத் திறமையையும் செல்வாக்கையும் அளிக்கிறது.",
