        astrological_principle_en="Dual Earth sign ruled by exalted Budha: Embodies methodical precision, discernment (Viveka), and capacity to heal and organize.",
        astrological_principle_ta="உபய பூமி ராசி: புதனின் நடைமுறை ஞானம் இவர்களை சிறந்த ஆராய்ச்சியாளர்களாகவும் திட்டமிடுபவர்களாகவும் மாற்றும்.",
