        name_en="Aquarius Ascendant (Kumbha Lagna - Visionary Humanism & Innovation)",
        name_ta="கும்ப லக்னம் (புரட்சிகர சிந்தனை, பொதுநலம், புதுமை & மனிதநேயம்)",
        category_slug="personality_birth",
