        version=1,
        name_en="Pisces Ascendant (Meena Lagna - Compassionate Empathy & Spiritual Imagination)",
        name_ta="மீன லக்னம் (எல்லையற்ற கருணை, கற்பனை வளம் & ஆன்மீக முக்தி நாட்டம்)",
        category_slug="personality_birth",
