        interpretation_en="If the cuspal sub-lord of the 6th or 10th house is the significator of 2 (bank balance), 6 (service rendered & receiving wages from employer), or 10 (profession/career), employment and consistent earning ability are guaranteed in life.",
        interpretation_ta="6 அல்லது 10-ஆம் பாவத்தின் உப அதிபதி 2 (தனம்), 6 (உத்தியோக ஊதியம்), 10 (தொழில் பதவி) ஆகிய பாவங்களை குறிக்கும் போது நிலையான வேலைவாய்ப்பும், தொடர் சம்பள வருமானமும் நிச்சயமாகக் கிட்டும்.",
