        interpretation_en="Promotion, elevated rank, honor, and enhanced income are promised when the 10th cuspal sub-lord signifies houses 2, 6, 10, and 11. The native ascends to prestigious management positions with substantial financial increments.",
        interpretation_ta="10-ஆம் உப அதிபதி 2, 6, 10, 11 பாவங்களை குறிக்கும் போது உத்தியோகத்தில் பதவி உயர்வு, சம்பள உயர்வு, மேலதிகாரிகளின் நன்மதிப்பு மற்றும் சமுதாய கௌரவம் நிச்சயமாகக் கிட்டும்.",
        astrological_principle_en="10th (status) + 11th (desires fulfilled & profits) + 2nd & 6th (salary increments) = definitive corporate and institutional promotion.",
