        interpretation_en="The tri-fold formula of KP wealth: When the 2nd cuspal sub-lord or dasha lords signify houses 2, 6, and 11, money flows consistently from vocational endeavors, investments, and customer revenues into solid savings.",
        interpretation_ta="கே.பி ஜோதிடத்தின் தன வரவு சூத்திரம்: 2, 6, 11 ஆகிய பாவங்கள் தசா-புக்திகளில் செயல்படும் போது தொழிலிலும் சேவையிலும் தொடர் பண வரவு உண்டாகி வங்கி இருப்பு பெருகும்.",
