        interpretation_ta="பங்குச் சந்தை மற்றும் ஊக வணிகத்தில் பெரும் லாபம் ஈட்ட 2, 5, 6, 11 ஆகிய பாவக தொடர்புகள் தேவை. 5-ஆம் பாவம் ஊக அறிவையும், 11-ஆம் பாவம் எதிர்பாராத லாபத்தையும் நல்கும்.",
        astrological_principle_en="5th governs speculative intelligence; 6th secures winning margins over market rivals; 11th harvests the financial bounty.",
        astrological_principle_ta="5-ஆம் பாவம் பங்குச் சந்தை நாட்டத்தையும் 11-ஆம் பாவம் வெற்றியையும் தரும்.",
