        interpretation_en="Constructing or purchasing a residential house or landed property is confirmed in KP when the 4th cuspal sub-lord signifies 4 (building/land), 11 (gain and possession), and 12 (investment of capital/payment to builder/seller).",
        interpretation_ta="4-ஆம் பாவத்தின் உப அதிபதி 4 (சொத்து/கட்டிடம்), 11 (சொந்தமாதல்), 12 (முதலீடு/கிரயத் தொகை செலுத்துதல்) ஆகிய பாவங்களை குறிக்கும் போது சொந்த வீடு, மனை வாங்கும் பாக்கியம் உறுதியாகிறது.",
        astrological_principle_en="KP doctrine: 4th (real estate) + 11th (acquisition) + 12th (capital expenditure to seller) completes the property transaction.",
        astrological_principle_ta="4-ஆம் பாவம் நிலத்தையும் 11-ஆம் பாவம் அதன் உடைமையையும் குறிப்பதால் சொத்து யோகம் உண்டாகிறது.",
        source_reference="Bhatt's Nakshatra Chintamani: Constructing a Building",
