        interpretation_en="Pluto in the 1st house emanates an intense, hypnotic, primal sexual magnetism. Possesses an aura that commands attention and deeply fascinates potential romantic partners.",
        interpretation_ta="லக்னத்தில் புளூட்டோ அமைந்திருப்பது தீவிரமான, வசீகரமான மற்றும் காந்தம் போன்ற உடலமைப்பு கவர்ச்சியை அளிக்கிறது. பிறரை சட்டென்று ஈர்க்கும் மர்மமான ஈர்ப்பு சக்தி இவர்களிடம் உண்டு.",
