        interpretation_en="Pluto in the 3rd house turns the voice and intellect into instruments of sexual seduction. Thrives on provocative texts, whispery dirty talk, and intense intellectual foreplay.",
        interpretation_ta="3-ஆம் பாவகத்தில் புளூட்டோ அமைந்திருப்பது வார்த்தைகள், உரையாடல்கள் மற்றும் குறுஞ்செய்திகளில் அந்தரங்கக் கவர்ச்சியையும் கிளர்ச்சியையும் தூண்டும் ஆற்றலை அளிக்கிறது.",
