        astrological_principle_ta="3-ஆம் பாவம் தகவல் தொடர்பைக் குறிக்கும். புளூட்டோ இங்கு அமையும் போது காமப் பேச்சுகளிலும் அந்தரங்க எழுத்துகளிலும் ஆழ்ந்த விருப்பம் உருவாகிறது.",
