        astrological_principle_ta="12-ஆம் பாவம் சயன சுகத்தைக் குறிக்கும். புளூட்டோ இங்கு அமைவது தீவிரமான படுக்கையறை இன்பத்தையும் ரகசிய கற்பனைகளையும் தருகிறது.",
