        name_en="Mars in Scorpio or 8th House - Fiery Sexual Stamina & Libido",
        name_ta="விருச்சிகம் அல்லது 8-ல் செவ்வாய் - தணியாத வீரியம் மற்றும் காம வேட்கை",
        interpretation_en="Mars in its own watery sign Scorpio or in the 8th house produces unyielding sexual drive, fierce physical passion, and profound stamina.",
        interpretation_ta="செவ்வாய் தனது ஆட்சி வீடான விருச்சிகத்திலோ அல்லது 8-ஆம் பாவகத்திலோ அமையும் போது எல்லையற்ற உடல் வீரியம், தீவிர காம வேட்கை மற்றும் இடைவிடாத உடலுறவு ஆற்றல் உண்டாகிறது.",
        astrological_principle_en="Mars is the governor of libido and physical energy. In Scorpio/8th house, Martian heat merges with water for unstoppable erotic endurance.",
