        name_en="Jupiter in Scorpio or 8th House - Uninhibited Sexual Openness",
        name_ta="விருச்சிகம் அல்லது 8-ல் குரு - குற்ற உணர்ச்சியற்ற வெளிப்படையான காம சுகம்",
        interpretation_en="Jupiter in Scorpio or the 8th house brings sexual liberation without shame or guilt, encouraging high philosophical and sensual exploration.",
        interpretation_ta="8-ஆம் பாவத்தில் அல்லது விருச்சிகத்தில் குரு அமைந்திருப்பது குற்ற உணர்ச்சியற்ற, தாராள மனப்பான்மையுடன் கூடிய ஆரோக்கியமான உல்லாச காம சுகத்தை அளிக்கிறது.",
