        astrological_principle_ta="8-ஆம் பாவம் அந்தரங்க உறுப்புகளையும் காம சுகத்தையும் குறிக்கும். குரு இங்கு அமையும் போது காமத்தில் பயமோ தயக்கமோ இன்றி முழு சுதந்திரமான அனுபவம் உண்டாகிறது.",
