        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="The 8th cusp lord is posited in an airy sign while its star lord is in a watery sign, indicating vulnerabilities related to water bodies, boat/flight travels, or liquid-related health hazards as described in classical KP literature.",
        interpretation_ta="8-ஆம் பாவ அதிபதி காற்று ராசியில் நின்று, அதன் சார நாதன் நீர் ராசியில் அமைகிறது. இது நீர் நிலைகள், படகு/விமானப் பயணங்கள் அல்லது திரவ சம்பந்தப்பட்ட உடல் உபாதைகள் மூலம் உண்டாகும் ஆபத்துகளைக் குறிக்கிறது.",
        astrological_principle_en="Decoded KP Manuscript Rule: 'If the 8th cusp lord is in an Airy sign and its star lord is in a watery sign, the native is prone to water-related danger while traveling. The 8th cusp indicates danger and fatality.'",
        astrological_principle_ta="கே.பி. மூல விதி: 8-ஆம் அதிபதி காற்று ராசியிலும், அதன் சார நாதன் நீர் ராசியிலும் அமையும் போது நீர்நிலைப் பயணங்களில் ஆபத்து ஏற்பட வாய்ப்புண்டு.",
