        interpretation_ta="8-ஆம் உப அதிபதி மாரக (2, 7) அல்லது பாதக ஸ்தான காரகனின் சாரத்தில் அமைகிறது. இது பலவீனமான தசா புக்தி காலங்களில் தீவிர விபத்து அல்லது உடல் காயங்கள் குறித்த எச்சரிக்கையைத் தருகிறது.",
        astrological_principle_en="Classical KP Rule: 'Accidents happen when 8th cusp sub-lord is deposited in the constellation of an 8th house significator. It turns fatal if posited in the star of a Badhaka or Maraka sthana significator.'",
        astrological_principle_ta="விபத்துக்கான கே.பி. விதி: 8-ஆம் உப அதிபதி 8-ஆம் பாவ காரக சாரத்தில் நின்று, மாரக/பாதக தொடர்பைப் பெற்றால் விபத்து அல்லது உயிராபத்து ஏற்படலாம்.",
