        astrology_system=AstrologySystem.KP,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="Event timing is dictated by the 4-fold hierarchy: Level 1 (Planet in star of occupant), Level 2 (Occupant), Level 3 (Planet in star of lord), and Level 4 (House lord). Events manifest during the joint period (DBAS) of these significators.",
        interpretation_ta="கே.பி. முறையில் நிகழ்வு நடக்கும் காலம் 4 அடுக்கு காரகத்துவங்களால் தீர்மானிக்கப்படுகிறது: நிலை 1 (பாவத்தில் நின்ற கிரக சாரத்தில் உள்ள கிரகம்), நிலை 2 (நின்ற கிரகம்), நிலை 3 (அதிபதி சாரத்தில் நின்ற கிரகம்), நிலை 4 (அதிபதி).",
        astrological_principle_en="Rahul Kaushik & KP Foundational Principle: 'The 4-level significators identify the planetary periods under which the event will unfailingly materialize.'",
        astrological_principle_ta="கே.பி. நிகழ்வு காலக் கணிப்பு: 4-அடுக்கு காரகர்களின் தசா-புக்தி-அந்தர இணைவில் நிகழ்வுகள் தப்பாமல் நடைபெறும்.",
