        category_slug="job_prospects",
        subcategory="planetary_strengths",
        astrology_system=AstrologySystem.KP,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="An event promised by the natal cuspal sub-lord crystallizes precisely when the Dasa Lord, Sun, and Moon transit the stars and subs of the Ruling Planets (Day lord, Moon sign/star lord, Lagna sign/star lord).",
        interpretation_ta="ஜாதகத்தில் உறுதியான ஒரு நிகழ்வு, தசா நாதன், சூரியன் மற்றும் சந்திரன் ஆகியோர் ஆளும் கிரகங்களின் (RP) நட்சத்திரம் மற்றும் உபநட்சத்திரத்தைக் கடக்கும் போது நடைமுறைக்கு வருகிறது.",
        astrological_principle_en="Rahul Kaushik & Decoded Manuscript Rule: 'At the time of the event, Sun, Moon, and the joint period rulers will be found in the star or sub of the same joint period ruler or ruling planets.'",
        astrological_principle_ta="கோச்சார விதி: நிகழ்வு நடக்கும் தருணத்தில் சூரியன், சந்திரன், தசா நாதர்கள் ஆளும் கிரகங்களின் சாரம் அல்லது உபசாரத்தில் சஞ்சரிப்பார்கள்.",
        source_reference="Decoded KP Manuscript & Rahul Kaushik Hidden Secrets",
