    # --- P. R. Muralidharan: Marriage Timing, Partner & Hometown Rules ---
    AstrologicalRuleDefinition(
        rule_id="RULE-MURL-MARR-01",
        name_en="Marriage Facilitating Houses - 5th & 9th House Synergy",
        name_ta="திருமணத்தை எளிதாக்கும் 5 மற்றும் 9-ஆம் பாவ யோகம்",
        category_slug="marriage_relationships",
        subcategory="first_marriage",
        astrology_system=AstrologySystem.KP,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="Houses 5 (12th from 6th - negating non-marriage, house of love) and 9 (12th from 10th, house of fortune) strongly facilitate the marital alliance when operating alongside marital houses 2, 7, and 11.",
        interpretation_ta="5-ஆம் பாவம் (6-க்கு 12 - திருமணம் மறுப்பை நீக்கும் காதல் பாவம்) மற்றும் 9-ஆம் பாவம் (பாக்கிய ஸ்தானம்) ஆகியவை 2, 7, 11 பாவங்களோடு இணையும் போது திருமணத்தை தடையின்றி எளிதாக நடத்துகிறது.",
        astrological_principle_en="P. R. Muralidharan KP Analysis: 'Houses 5 and 9 will always facilitate marriage. 5th being 12th from 6th negates no-marriage; 9th is house of Fortune and 12th from 10th.'",
        astrological_principle_ta="பி. ஆர். முரளிதரன் கே.பி. ஆய்வு: 5 மற்றும் 9-ஆம் பாவங்கள் திருமணத்தை எப்போதும் எளிதாக்குகின்றன; 5-ஆம் பாவம் 6-க்கு 12 ஆகி திருமண மறுப்பை நீக்குகிறது.",
        source_reference="P. R. Muralidharan - KP Analysis of Marriage and its Timing",
        severity=SeverityLevel.FAVORABLE,
        condition_tree={
            "type": "kp_significator",
            "cusp": 7,
            "required_houses": [5, 9, 11],
            "match_mode": "any"
        }
    ),
    AstrologicalRuleDefinition(
        rule_id="RULE-MURL-MARR-02",
        name_en="Saturn Delay Mitigated by Jupiter's Trine Aspect",
        name_ta="சனி தரும் திருமண தாமதத்தை நீக்கும் குருவின் பார்வை",
        category_slug="marriage_relationships",
        subcategory="delayed_marriage",
        astrology_system=AstrologySystem.VEDIC,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="While Saturn aspecting marital houses (2, 7, 11) typically causes severe delay in matchmaking, Jupiter's 9th or trine aspect on Saturn fully mitigates the delay, conferring an honorable, mature spouse.",
        interpretation_ta="சனி 2, 7, 11 ஆகிய திருமண பாவங்களைப் பார்க்கும் போது கடுமையான காலதாமதம் ஏற்பட்டாலும், குரு பகவான் சனியை 9-ஆம் பார்வையாகவோ அல்லது திரிகோண பார்வையாகவோ பார்க்கும் போது அனைத்து தோஷங்களும் நீங்கி நல்ல வரன் அமையும்.",
        astrological_principle_en="P. R. Muralidharan Principle: 'Saturn aspecting 2, 7, 11 delays marriage very much. However, Jupiter aspecting Saturn in Trine mitigates all the evil effects of Saturn, which is most beneficial.'",
        astrological_principle_ta="முரளிதரன் விதி: சனியின் பார்வையை குருவின் திரிகோண பார்வை சமன் செய்து திருமணத் தடைகளை முற்றிலும் நீக்குகிறது.",
        source_reference="P. R. Muralidharan - KP Analysis of Marriage and its Timing",
        severity=SeverityLevel.FAVORABLE,
        condition_tree={
            "type": "planet_aspect",
            "aspecting_planet": "Jupiter",
            "target_type": "planet",
            "target_value": "Saturn",
            "chart": "d1"
        }
    ),
    AstrologicalRuleDefinition(
        rule_id="RULE-MURL-MARR-03",
        name_en="Spouse's Distance - Hometown vs. Distant / Foreign Origin",
        name_ta="வாழ்க்கைத் துணையின் இருப்பிடம் - சொந்த ஊர் அல்லது தூர தேசம்",
        category_slug="marriage_relationships",
        subcategory="spouse_characteristics",
        astrology_system=AstrologySystem.KP,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="The 7th cusp sub-lord's links determine spouse's origin: 10th house indicates hometown partner; 3rd indicates neighbor/short distance; 9th or 12th indicates stranger from long distance or foreign land.",
        interpretation_ta="7-ஆம் உப அதிபதி 10-ஆம் பாவம் தொடர்பு பெற்றால் சொந்த ஊர் துணைவர்; 3-ஆம் பாவம் அருகிலுள்ளவர்/பக்கத்து ஊர்; 9 அல்லது 12-ஆம் பாவம் தூர தேசம், வெளிநாடு அல்லது முற்றிலும் புதிய அறிமுகத்தைக் குறிக்கிறது.",
        astrological_principle_en="P. R. Muralidharan: 'Tenth house means partner is from home town; 3rd signifies short distance (co-tenant, street, town); 9th signifies long distance, stranger, or foreign country.'",
        astrological_principle_ta="துணைவரின் தூரம்: 10-ஆம் பாவம் சொந்த ஊர், 3-ஆம் பாவம் குறுகிய தூரம், 9 மற்றும் 12-ஆம் பாவங்கள் நீண்ட தூரம் மற்றும் வெளிநாடு.",
        source_reference="P. R. Muralidharan - KP Analysis of Marriage and its Timing",
        severity=SeverityLevel.NEUTRAL,
        condition_tree={
            "type": "kp_significator",
            "cusp": 7,
            "required_houses": [3, 9, 10, 12],
            "match_mode": "any"
        }
    ),
