        name_en="Spouse's Profession - Engineering / Electronics / IT Nexus",
        name_ta="வாழ்க்கைத் துணையின் தொழில் - பொறியியல், தகவல் தொழில்நுட்பம்",
        category_slug="marriage_relationships",
        subcategory="spouse_characteristics",
        astrology_system=AstrologySystem.KP,
        chart_scope=ChartScope.D1,
        calculation_mode="thirukanitha",
        interpretation_en="The significators of 4, 8, and 12 denote spouse's profession. Venus with Uranus/Mercury indicates electronics, computer engineering, software, and management finance.",
        interpretation_ta="4, 8, 12 பாவங்களின் காரகர்கள் துணைவரின் தொழிலைக் குறிக்கும். சுக்கிரன், புதன் மற்றும் யுரேனஸ் தொடர்புகள் மென்பொருள், எலக்ட்ரானிக்ஸ், கம்ப்யூட்டர் சயின்ஸ் அல்லது நிதி நிர்வாகத் தொழிலைக் குறிக்கின்றன.",
        astrological_principle_en="P. R. Muralidharan: 'Significators of 4, 8, and 12 denote the profession of the partner. Venus with Uranus signifies electronics; Mercury engineering and computers; Jupiter finance and law.'",
        astrological_principle_ta="துணைவர் தொழில்: 4, 8, 12 பாவங்கள் துணைவரின் தொழிலைக் காட்டும். சுக்கிரன், புதன் சேர்க்கை தொழில்நுட்ப மற்றும் கணினி பொறியியலைத் தரும்.",
        source_reference="P. R. Muralidharan - KP Analysis of Marriage and its Timing",
        severity=SeverityLevel.FAVORABLE,
        condition_tree={
            "type": "kp_significator",
            "cusp": 7,
            "required_houses": [4, 8, 12],
            "match_mode": "any"
        }
