        interpretation_ta="5-ஆம் உப அதிபதி 5 மற்றும் 8-ஆம் பாவங்களைக் குறிக்கும் போது சமூகம் மற்றும் குடும்பத்திற்குத் தெரியாத மறைமுக ரகசிய காதல் உறவு உண்டாகிறது. 8-ஆம் பாவம் 9-க்கு 12 என்பதால் நிதானம் தேவை.",
