        calculation_mode="thirukanitha",
        interpretation_en="The 5th cusp sub-lord signifies 5, 8, and 12 without 11th house backing, indicating an affair anchored purely on physical passion and bed pleasures that does not convert into matrimony.",
        interpretation_ta="5-ஆம் உப அதிபதி 5, 8 மற்றும் 12-ஆம் பாவங்களைக் குறித்து 11-ஆம் பாவம் இல்லாமல் அமையுமாயின், அது உடல் இன்பக் கவர்ச்சியோடு நின்று திருமண பந்தமாக மாறாது.",
